const [year, month, day] = fechaPart.split('-');
const fechaFormateada = `${day}/${month}/${year}`;
const horaInicio = horaInicioFull.substring(0, 5);
const horaFin = cal.endTime.split('T')[1].substring(0, 5);
const params = {
  x: "REEMPLAZAR_SKYIA_API_KEY",
  api: "postAgendaEvento",
  idAgenda: parseInt("2"),
  idRecurso: idProfesional,
  idPaciente: $input.first().json.idPaciente,
  idProducto: idProducto,
  fecha: fechaFormateada,
  horaInicio: horaInicio,
  horaFin: horaFin,
};
const baseUrl = "https://api.cloud.skyia.ar/skyia_api";
const queryArray = [];
for (const key in params) {
  if (params[key] !== "" && params[key] !== null) {
    queryArray.push(`${key}=${encodeURIComponent(params[key])}`);
  }
}
const urlFinal = `${baseUrl}?${queryArray.join('&')}`;

return [{ 
  json: { 
    urlReserva: urlFinal, 
    idAsignado: idProfesional, 
    idProducto: idProducto, 
    productoDetectado: motivoConsulta, 
    datosMapeados: params 
  } 
}];

